    for r in range(H):
        for c in range(W):
            if A[r,c]==v and not seen[r,c]:
                q=deque([(r,c)]); seen[r,c]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and A[x,y]==v and not seen[x,y]:
