    for v in np.unique(A):
        for c in comps(A,v): cnt[v].append(norm(c))
    bg=Counter(A.flatten()).most_common(1)[0][0]
    sgl=sorted(((v,len(cs)) for v,cs in cnt.items() if len(cs)==1 and v!=bg),key=lambda t:-t[1])
    # pick most frequent (largest area) singleton color
    news=sgl[0][0]
